// Legacy assistant jobs can still return private browser playback. They must
// never be mixed into the human microphone identity; native personas publish
// shared TTS through their own room transport.
let personaAudioTail=Promise.resolve();
function playPersonaReply(result,roomId){
 if(result.sharedRoomAudio||result.personaSpeech?.attempted)return Promise.resolve();
 if(!result.audioUrl)return Promise.resolve();
 const task=personaAudioTail.then(async()=>{
  if(activeRoom!==roomId)return;
  const audio=new Audio(result.audioUrl);
  audio.controls=true;audio.dataset.personaReply='';detail.querySelector('[data-persona-reply]')?.remove();detail.querySelector('.hmo-dj-card')?.append(audio);
  try{
   await new Promise((resolve,reject)=>{
    let timer,watch;const finish=(error)=>{clearTimeout(timer);clearInterval(watch);audio.pause();error?reject(error):resolve()};
    timer=setTimeout(()=>finish(),180000);watch=setInterval(()=>{if(activeRoom!==roomId)finish()},250);
    audio.onended=()=>finish();audio.onerror=()=>finish(new Error('Room reply audio failed'));
    audio.play().catch(()=>{audio.title='Press play to hear this reply'});
   });
  }finally{audio.remove()}
 });personaAudioTail=task.catch(()=>{});return task;
}
