async function enableMic(){try{const noise=detail.querySelector('[data-noise]')?.checked??true,echo=detail.querySelector('[data-echo]')?.checked??true,agc=detail.querySelector('[data-agc]')?.checked??true,device=detail.querySelector('[data-mic-device]')?.value||'';if(micStream)for(const track of micStream.getTracks())track.stop();micStream=await navigator.mediaDevices.getUserMedia({audio:{noiseSuppression:noise,echoCancellation:echo,autoGainControl:agc,...(device?{deviceId:{exact:device}}:{})}});micMuted=false;setMuted(ptt);audioContext?.close?.();audioContext=new AudioContext();const source=audioContext.createMediaStreamSource(micStream);analyser=audioContext.createAnalyser();analyser.fftSize=256;source.connect(analyser);meter();await rtc?.setInput(micStream);await rtc?.resumeAudio();await enumerateAudioDevices()}catch(e){alert('Mic blocked: '+msg(e))}}
