async function enumerateAudioDevices(){if(!navigator.mediaDevices?.enumerateDevices)return;const input=detail.querySelector('[data-mic-device]'),output=detail.querySelector('[data-output-device]'),devices=await navigator.mediaDevices.enumerateDevices();if(input){const prior=input.value||localStorage.getItem('hmo-input-device')||'';input.replaceChildren(new Option('Default microphone',''),...devices.filter(d=>d.kind==='audioinput').map((d,i)=>new Option(d.label||'Microphone '+(i+1),d.deviceId)));input.value=prior;input.addEventListener('change',()=>{localStorage.setItem('hmo-input-device',input.value);if(micStream)void enableMic()},{once:true})}if(output){const prior=output.value||localStorage.getItem('hmo-output-device')||'';output.replaceChildren(new Option('Default output',''),...devices.filter(d=>d.kind==='audiooutput').map((d,i)=>new Option(d.label||'Output '+(i+1),d.deviceId)));output.value=prior;output.addEventListener('change',()=>{localStorage.setItem('hmo-output-device',output.value);void applyOutputDevice(output.value)},{once:true})}}
