function relativeTime(value){const t=Date.parse(value||'');if(!Number.isFinite(t))return'time unavailable';const ms=Math.max(0,Date.now()-t),m=Math.floor(ms/60000);if(m<1)return'just now';if(m<60)return m+'m ago';const h=Math.floor(m/60);return h<24?h+'h ago':Math.floor(h/24)+'d ago'}
