async function resolvePrincipal(request:IncomingMessage,spmtOrigin:string):Promise<HearMeOutPrincipalV1>{const headers:Record<string,string>={accept:"application/json","x-spmt-app":"hearmeout"};if(request.headers.cookie)headers.cookie=request.headers.cookie;const response=await fetch(`${spmtOrigin}/v1/session`,{headers,redirect:"manual",signal:AbortSignal.timeout(5000)});if(!response.ok)throw Object.assign(new Error(response.status===401||response.status===403?"Sign in to SpaceMountain before using Hear Me Out":"SPMT session service is temporarily unavailable"),{status:response.status===401||response.status===403?401:503});const value=await response.json() as Record<string,unknown>,userId=typeof value.actorId==="string"?value.actorId:"",tenantId=Array.isArray(value.tenantIds)&&typeof value.tenantIds[0]==="string"?value.tenantIds[0]:"",scopes=Array.isArray(value.scopes)?value.scopes.filter((item):item is string=>typeof item==="string"):[];if(!userId||!tenantId)throw new Error("SPMT session has no user or tenant");const admin=scopes.some(scope=>scope==="*"||scope==="admin"||scope.startsWith("admin:")||scope.endsWith(":any")),displayName=typeof value.displayName==="string"&&value.displayName.trim()?value.displayName.trim():typeof value.username==="string"&&value.username.trim()?value.username.trim():userId;return{tenantId,userId,displayName,roles:admin?["admin"]:["member"]};}
function makeRoomId(name:string){const slug=name.toLowerCase().normalize("NFKD").replace(/[^a-z0-9]+/g,"-").replace(/^-+|-+$/g,"").slice(0,48)||"room";return`${slug}-${Date.now().toString(36)}-${randomBytes(3).toString("hex")}`;}
async function readJson(request:IncomingMessage,maxBytes=MAX_BODY_BYTES):Promise<Record<string,unknown>>{const chunks:Buffer[]=[];let total=0;for await(const chunk of request){const part=Buffer.isBuffer(chunk)?chunk:Buffer.from(chunk);total+=part.byteLength;if(total>maxBytes)throw new Error("HearMeOut request body is too large");chunks.push(part)}if(!chunks.length)return{};const parsed=JSON.parse(Buffer.concat(chunks).toString("utf8"));if(!parsed||typeof parsed!=="object"||Array.isArray(parsed))throw new Error("HearMeOut request must be a JSON object");return parsed as Record<string,unknown>;}
function requiredText(value:unknown,name:string,max:number){if(typeof value!=="string"||!value.trim()||value.trim()!==value||value.length>max||/[\r\n\0]/.test(value))throw new Error(`HearMeOut ${name} is invalid`);return value;}
function cleanLabel(value:unknown,name:string,max:number){const text=String(value??"").trim();if(!text||text.length>max||/[\r\n\0]/.test(text))throw new Error(`HearMeOut ${name} is invalid`);return text;}
function cleanMessage(value:unknown){const text=String(value??"").trim();if(!text||text.length>2000||/\0/.test(text))throw new Error("HearMeOut chat message is invalid");return text;}
function cleanId(value:unknown,name:string){const text=String(value??"").trim();if(!/^[A-Za-z0-9._:@/-]{1,200}$/.test(text))throw new Error(`HearMeOut ${name} is invalid`);return text;}
function personaAssets(value:{avatarUrl?:string;idleAvatarUrl?:string;talkingAvatarUrl?:string}){const result:Record<string,string>={};for(const key of ["avatarUrl","idleAvatarUrl","talkingAvatarUrl"] as const){const input=value[key];if(!input)continue;const url=new URL(input);if(url.protocol!=="https:"||url.username||url.password)throw new Error("HearMeOut persona avatar URL is invalid");result[key]=url.toString()}return result;}
function playableUrl(value:unknown){if(typeof value!=="string"||!value.trim()||value.length>3000)throw new Error("HearMeOut playback URL is invalid");let url:URL;try{url=new URL(value)}catch{throw new Error("HearMeOut playback URL is invalid")};if(url.protocol!=="https:"&&url.protocol!=="http:")throw new Error("HearMeOut playback URL must use HTTP or HTTPS");if(url.username||url.password)throw new Error("HearMeOut playback URL cannot contain credentials");return url.toString();}
function optionalDuration(value:unknown){if(value===undefined||value===null||value==="")return undefined;const n=Math.trunc(Number(value));if(!Number.isSafeInteger(n)||n<0||n>24*60*60)throw new Error("HearMeOut duration is invalid");return n;}
function requireSameOrigin(request:IncomingMessage){const origin=request.headers.origin;if(!origin)return;const host=request.headers.host;if(!host||new URL(origin).host!==host)throw new Error("HearMeOut request origin is invalid");}
function loopbackOrigin(value:string){const url=new URL(value);if(url.protocol!=="http:"||!["127.0.0.1","localhost","::1","[::1]"].includes(url.hostname)||url.username||url.password||url.pathname!=="/"||url.search||url.hash)throw new Error("SPMT_ORIGIN must be a credential-free loopback HTTP origin");return url.origin;}
function send(response:ServerResponse,status:number,body:string,type:string){const encoded=Buffer.from(body);response.writeHead(status,{"content-type":type,"content-length":encoded.byteLength,"cache-control":"no-store","x-content-type-options":"nosniff"});response.end(encoded);}
function sendJson(response:ServerResponse,status:number,value:unknown){send(response,status,JSON.stringify(value),"application/json; charset=utf-8");}
function applyPageHeaders(response:ServerResponse){response.setHeader("content-security-policy","default-src 'none'; script-src 'self' blob: 'unsafe-inline'; style-src 'unsafe-inline'; img-src 'self' data:; connect-src 'self' wss:; worker-src 'self' blob:; frame-src 'self'; media-src 'self' https: http: blob:; base-uri 'none'; form-action 'self'; frame-ancestors 'self'; object-src 'none'");response.setHeader("permissions-policy","camera=(), microphone=(self), geolocation=(), payment=(), usb=(), serial=(), bluetooth=()");response.setHeader("referrer-policy","no-referrer");response.setHeader("x-frame-options","SAMEORIGIN");}
function listen(server:ReturnType<typeof createServer>,port:number,host:string){return new Promise<void>((done,reject)=>{server.once("error",reject);server.listen(port,host,()=>{server.off("error",reject);done()})});}
function close(server:ReturnType<typeof createServer>){return new Promise<void>((done,reject)=>server.close(error=>error?reject(error):done()));}
function safeError(error:unknown){return(error instanceof Error?error.message:String(error??"HearMeOut request failed")).replace(/((?:token|authorization|secret|password|cookie))\s*[:=]\s*\S+/gi,"$1=[redacted]").slice(0,400);}
function escapeHtml(value:string){return value.replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"})[c]!);}
